            }
            if (k == 5) {
                String[] words = {"true", "TRUE", "True", "yes", "YES", "Yes", "on", "ON", "off", "no", "false", "tru", ""};
                return words[r.nextInt(words.length)];
            }
            if (k == 6) {
                // near misses of length 3 starting with t/T
                return "" + pick(r, 't') + rand(r, 2);
            }
            return rand(r, r.nextInt(7));
        }
    }

